KG42.register("clusters-89af7ab4ea7c5a9fe9b3673b",{"id":"43-operating_envelope_ev_market::v142-d-K003","paper":"43-operating_envelope_ev_market","label":"Joint buy and sell bidding under DOE constraints.","record":{"cluster_id":"v142-d-K003","label":"Joint buy and sell bidding under DOE constraints.","market_meaning":"Prosumers choose the buy and sell quantities submitted to peers and the upper grid through joint transaction-cost optimization; imports and exports are respectively restricted by their DOE conditional branches, and the total P2P bid purchase quantity and the signed total sale quantity must balance. The current candidate retains the unresolved problems of unclosed quantity obligations and inactive branches.","mechanism_ids":["v141-a-M03-lem"],"market_types":["LEM"],"process_stages":["participation","bidding"],"scope_disposition":"conditional","scope_explanation":"Participation choice is realized through the same bidding strategy; the positive-DOE import branch and the non-positive-DOE export branch are retained separately, and the two branches cannot both be imposed unconditionally on every prosumer. Prices here serve only as objective coefficients and are not automatically equated with subsequent bilateral clearing prices.","assembly_status":"partial","boundary_rationale":"Demand bids and supply bids are complementary sides of the same joint optimization and cannot be split by node into independent optimization rules; their result is a total-quantity bid, and bilateral allocation and price formation belong to subsequent independent decisions.","chain_bindings":[{"chain_id":"v141-c-R003","ownership":"primary","role":"core","rationale":"Provide the import-side peer and grid purchase quantity bids and the DOE limit."},{"chain_id":"v141-c-R004","ownership":"primary","role":"core","rationale":"Complete the signed sale branch, the joint cost objective, and the total P2P balance to form the same buy/sell bidding decision."},{"chain_id":"v141-c-R008","ownership":"shared","role":"interface","rationale":"Explain that participation and channel choice are realized through buy/sell bids; the primary attribution is in v142-d-K002, and this is not counted again here as an independent permission rule."}],"connections":[{"connection_id":"v142-d-K003-L01","from_chain_id":"v141-c-R008","to_chain_id":"v141-c-R003","kind":"functional_coupling","from_refs":["v141-c-R008::phi::v141-c-R008-C002"],"to_refs":["v141-c-R003::phi::v141-c-R003-C001","v141-c-R003::phi::v141-c-R003-C003"],"evidence_ids":["v141-b-g02-E27"],"rationale":"The source explicitly implements trading participation choice as generating and submitting buy/sell bids within the DOE; this connection records the functional realization on the purchase side and does not add a participation decision variable."},{"connection_id":"v142-d-K003-L02","from_chain_id":"v141-c-R008","to_chain_id":"v141-c-R004","kind":"functional_coupling","from_refs":["v141-c-R008::phi::v141-c-R008-C002"],"to_refs":["v141-c-R004::phi::v141-c-R004-C002","v141-c-R004::phi::v141-c-R004-C003"],"evidence_ids":["v141-b-g02-E27"],"rationale":"The sale side likewise belongs to the participation choice and joint cost optimization described in the source; no separate participation or bidding problem is established."},{"connection_id":"v142-d-K003-L03","from_chain_id":"v141-c-R003","to_chain_id":"v141-c-R004","kind":"functional_coupling","from_refs":["v141-c-R003::phi::v141-c-R003-C002","v141-c-R003::phi::v141-c-R003-C003"],"to_refs":["v141-c-R004::phi::v141-c-R004-C001","v141-c-R004::phi::v141-c-R004-C003","v141-c-R004::phi::v141-c-R004-C004"],"evidence_ids":["v141-b-g02-E27","v141-b-g02-E28","v141-b-g02-E29","v141-b-g02-E30","v141-b-g02-E31"],"rationale":"The import limit, export limit, and total P2P balance jointly constrain the same joint bidding objective; their respective conditions remain unchanged, and no new cross-chain scientific edge is added."}],"object_mappings":[{"mapping_id":"v142-d-K003-M01","kind":"same_node","member_refs":["v141-c-R003::V::bidding.demand","v141-c-R004::V::bidding.demand"],"canonical_ref":"v141-c-R003::V::bidding.demand","display_policy":"single_representative","evidence_ids":["v141-b-g02-E27","v141-b-g02-E31"],"rationale":"The two chains reference the same demand-bid node; the original objects of the joint objective and the supply-demand balance are both retained."},{"mapping_id":"v142-d-K003-M02","kind":"same_quantity","member_refs":["v141-c-R003::x::v141-c-R003-x-Ppb","v141-c-R004::x::x-Ppb-jt"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-E27","v141-b-g02-E29","v141-b-g02-E33"],"rationale":"The source defines both as the total P2P purchase bid quantity of the same prosumer in the same period; their local roles on the demand side and in the joint optimization are retained."},{"mapping_id":"v142-d-K003-M03","kind":"same_quantity","member_refs":["v141-c-R003::x::v141-c-R003-x-Pgb","v141-c-R004::x::x-Pgb-jt"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-E27","v141-b-g02-E30"],"rationale":"Both objects point to the upper-grid purchase bid quantity for the same period; only a quantity correspondence is established, and the objects are not rewritten."},{"mapping_id":"v142-d-K003-M04","kind":"same_quantity","member_refs":["v141-c-R003::theta::v141-c-R003-theta-DOE","v141-c-R004::theta::theta-Phat-jt"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-E28","v141-b-g02-E29","v141-b-g02-E30"],"rationale":"The same allocated DOE is used in R003 only for the import branch and in R004 covers both sign branches; the correspondence holds only within their respective conditions, and the import object is not expanded into an export constraint."}],"gaps":[{"gap_id":"v142-d-K003-G01","category":"unverified_source","description":"The transcriptions of the joint objective, DOE branches, and total-quantity balance have not undergone independent source review.","chain_ids":["v141-c-R003","v141-c-R004","v141-c-R008"],"object_refs":["v141-c-R003::phi::v141-c-R003-C002","v141-c-R004::phi::v141-c-R004-C001","v141-c-R004::phi::v141-c-R004-C003","v141-c-R004::phi::v141-c-R004-C004","v141-c-R008::phi::v141-c-R008-C002"],"evidence_ids":["v141-b-g02-E27","v141-b-g02-E28","v141-b-g02-E29","v141-b-g02-E30","v141-b-g02-E31","v141-b-g02-E33"],"proposal_ids":[],"required_work":"Manually verify the objective, sale signs, conditional branches, and constraint scope; retain the experimental candidate status and do not claim that independent review has been completed."},{"gap_id":"v142-d-K003-G02","category":"math_incomplete","description":"The frozen constraints do not explicitly close the inactive buy/sell branches: the sale lower bound under the import condition and the purchase limit under the export condition are not fully specified, and cross-branch arbitrage or unbounded directions cannot be ruled out.","chain_ids":["v141-c-R003","v141-c-R004"],"object_refs":["v141-c-R003::phi::v141-c-R003-C002","v141-c-R004::phi::v141-c-R004-C003","v141-c-R004::phi::v141-c-R004-C004","v141-c-R004::x::x-Ppb-jt","v141-c-R004::x::x-Pps-jt","v141-c-R004::x::x-Pgb-jt","v141-c-R004::x::x-Pgs-jt"],"evidence_ids":["v141-b-g02-E27","v141-b-g02-E28","v141-b-g02-E29","v141-b-g02-E30"],"proposal_ids":[],"required_work":"Have upstream verify the complete variable domains, inactive-branch restrictions, and price conditions and establish boundedness; D does not add zero-value conditions or missing constraints."},{"gap_id":"v142-d-K003-G03","category":"math_incomplete","description":"The DOE limits and total P2P balance do not connect bid quantities to net demand that must be met or to delivered quantities; it cannot be inferred from cost minimization alone that demand is satisfied or that the DOE is necessarily fully used, nor can the sample equality result in Fig.10 be turned into a general equation.","chain_ids":["v141-c-R003","v141-c-R004"],"object_refs":["v141-c-R003::phi::v141-c-R003-C002","v141-c-R003::phi::v141-c-R003-C003","v141-c-R004::phi::v141-c-R004-C001","v141-c-R004::phi::v141-c-R004-C003","v141-c-R004::phi::v141-c-R004-C004"],"evidence_ids":["v141-b-g02-E27","v141-b-g02-E28","v141-b-g02-E31","v141-b-g03-e010"],"proposal_ids":[],"required_work":"Check whether net-demand satisfaction, quantity conservation, or other trading obligations are omitted, and have C complete the source-supported content; before that, do not claim that the optimization fully satisfies energy demand."},{"gap_id":"v142-d-K003-G04","category":"ontology_extension","description":"The DOE still appears as a frozen parameter, and its calculation and network-constraint sources have no corresponding complete chain; the existing DOE node proposal remains pending.","chain_ids":["v141-c-R003","v141-c-R004"],"object_refs":["v141-c-R003::theta::v141-c-R003-theta-DOE","v141-c-R004::theta::theta-Phat-jt"],"evidence_ids":["v141-b-g02-E28","v141-b-g02-E29","v141-b-g02-E30"],"proposal_ids":["proposal:v141-b-g01-doe","proposal:v141-b-g02-P01","v141-b-g03-p01-doe"],"required_work":"Retain the DOE as an externally given input; if its calculation or ontology extension needs to be traced, handle the proposal manually and supplement it upstream, without substituting a same-name parameter reference for the missing mechanism."}]},"rule_refs":["43-operating_envelope_ev_market::v141-c-R003","43-operating_envelope_ev_market::v141-c-R004","43-operating_envelope_ev_market::v141-c-R008"],"unresolved_rule_refs":[],"node_ids":["COMP-4fd16cbd90d234cb","COMP-b3f649e90c1f17b9","COMP-b9841ac99d9d29b8"]});
